function countBy(rows,key){return rows.reduce((all,row)=>(all[row[key]]=(all[row[key]]||0)+1,all),{});}
(async()=>{fs.mkdirSync(output,{recursive:true});const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_BIN||'/usr/bin/chromium',args:['--no-sandbox']}),reports=[];try{for(const entry of matrix){const report=await runBuild(browser,entry);reports.push(report);fs.writeFileSync(path.join(output,'interactions-'+entry.label+'.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({mode:report.label,passed:report.passed,documents:report.documents,counts:report.counts,failures:report.failed,unclassified:report.unclassified_visible_enabled.map(r=>({route:r.route,id:r.id,selector:r.selector,label:r.label}))}));}}finally{await browser.close();}const report={passed:reports.every(r=>r.passed),inventory_only:inventoryOnly,reports};fs.writeFileSync(path.join(output,'interactions-final.json'),JSON.stringify(report,null,2)+'\n');if(!inventoryOnly&&!report.passed)process.exitCode=1;})().catch(error=>{console.error(error);process.exitCode=1;});
